    "sourceCandidatePath": "drafts/seo/fc-20260925-organic-query-page-completion-v1/kitchen-cabinet-price-cms-candidate-v1.json",
    "sourceCandidateSha256": "63be90190ad6423ae195ca8ece1b8fe1c4d1ed097d8945adb65cb06114719f99",
    "rollbackPackagePath": "backups/fc-20260925-organic-query-page-completion-v1/kitchen-cabinet-price-current-row.json",
    "rollbackPackageSha256": "7821ff2f84daf4ab01cf707ef2f75fe29c80efefe941f095c349dacef8c7c3e9",
    "rollbackRecordPath": "backups/fc-20260925-organic-query-page-completion-v1/kitchen-cabinet-price-current-row.json",
    "rollbackRecordSha256": "7821ff2f84daf4ab01cf707ef2f75fe29c80efefe941f095c349dacef8c7c3e9",
