    "expectedUpdatedAt": "2026-08-22T12:23:13.790058+00:00",
    "status": "published",
    "baselineFieldsSha256": "50b0c1510443cb59996e12117ad374ede0f279b4d1658cacb74d43d014f47704",
    "desiredFieldsSha256": "4bca36e72073660d3328e6241cb3128c97b2c4a0230a17d2a5a2645726cf755f",
